// #772789 (db1dba9783e89397fd772789) «iOS/Web - «תזכורות מהירות» ממשיך להציג תזכורת לתפילה שהמשתמש כבר התפלל ורשם» — עבר QA 25.10.2026.
// מה רצוי: после записи молитвы её напоминание в «תזכורות מהירות» не показывается; прочие остаются (F-47 + решение владельца 20.10).
// Факт 25.10 17:05 (user1, веб; .qa/screenshots/772789-2510-web-*.png): «ערבית» / «אפשר להתפלל עכשיו, עד …» после שקיעה →
//   /prayer/arvit_ashkenaz, «סיים תפילה» на 1-м קטע → POST prayer_completions 201 → «כל הכבוד!» «סיימת את תפילת ערבית בהצלחה» →
//   «חזרה למסך ראשי» → «ערבית» исчезла, «לראש חודש» / «תזכורת יומית בשעה 15:00» на месте, «תפילות אחרונות» — «ערבית» «ט״ו חשון · 17:06»;
//   2 reload + новая вкладка — не вернулась.
// Реальное время (без подмены часов: запись пишется сервером по реальному времени). Нет карточки «<молитва> · אפשר להתפלל עכשיו» — skip.
// @data: добавляет запись молитвы user1 (необратимо). Не запускался при записи — первый прогон через /qa-regress.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';
import { readReminders, ReminderRow } from '../_helpers/reminders';
import { suppressMilestoneWindow } from '../_helpers/milestone';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
  timezoneId: 'Asia/Jerusalem',
});

const PRAYER_IDS: Record<string, string> = { 'שחרית': 'shacharit', 'מנחה': 'mincha', 'ערבית': 'arvit' };
const NUSACH_IDS: Record<string, string> = { 'אשכנז': 'ashkenaz', 'ספרד': 'sfarad' };
const NOW = 'אפשר להתפלל עכשיו';
const RECENT_WHEN = /^[א-ת״׳' ]+ · \d{2}:\d{2}(:\d{2})?$/;

const openPrayerRow = (rows: ReminderRow[]) => rows.find((r) => r.title in PRAYER_IDS && r.sub.startsWith(NOW));

/** Первая строка «תפילות אחרונות»: текст карточки (тип + «<евр. дата> · HH:MM»). */
async function recentFirst(page: Page): Promise<{ prayer: string; when: string }> {
  await expect(page.getByText('תפילות אחרונות', { exact: true })).toBeVisible({ timeout: 20_000 });
  const when = page.getByText(RECENT_WHEN).first();
  await expect(when).toBeVisible();
  const card = await when.evaluate((el) => {
    let n: HTMLElement | null = el as HTMLElement;
    while (n && !/(שחרית|מנחה|ערבית)/.test(n.innerText)) n = n.parentElement;
    return n?.innerText ?? '';
  });
  return { prayer: (card.match(/שחרית|מנחה|ערבית/) ?? [''])[0], when: (await when.innerText()).trim() };
}

async function homeReminders(page: Page): Promise<ReminderRow[]> {
  await page.goto('/home');
  return readReminders(page);
}

test.describe('Напоминания', () => {
  test('RM-11 Запись молитвы с открытым окном → её строка исчезает из «תזכורות מהירות», прочие на месте, «תפילות אחרונות» первая; 2 reload + новая вкладка #db1dba97 #772789 @data @mobile', async ({ page, context }) => {
    test.setTimeout(120_000);
    await suppressMilestoneWindow(page); // окно уровня не должно перекрывать «כל הכבוד!»

    // 1. /home → «תזכורות מהירות»: строка молитвы «אפשר להתפלל עכשיו, עד HH:MM».
    const before = await homeReminders(page);
    const open = openPrayerRow(before);
    test.skip(!open, `сейчас нет молитвы с открытым окном, не записанной сегодня (строки: ${before.map((r) => r.title).join(', ')}) — повторить после שקיעה (ערבית) или в окне מנחה`);
    const prayer = open!.title;
    expect(open!.sub).toMatch(/עד \d{1,2}:\d{2}/);
    const others = before.filter((r) => !(r.title in PRAYER_IDS)).map((r) => r.title);
    const cardText = await page.getByRole('button', { name: 'התחל תפילה' }).locator('xpath=..').innerText().catch(() => '');
    const nusach = NUSACH_IDS[cardText.match(/נוסח (אשכנז|ספרד)/)?.[1] ?? 'אשכנז'];

    // 2. /prayer/<молитва>_<нусах> → «סיים תפילה» на 1-м קטע → POST prayer_completions 201.
    await page.goto(`/prayer/${PRAYER_IDS[prayer]}_${nusach}`);
    const finish = page.getByRole('button', { name: 'סיים תפילה' });
    await expect(finish).toBeEnabled({ timeout: 20_000 });
    const post = page.waitForResponse((r) => r.url().includes('/rest/v1/prayer_completions') && r.request().method() === 'POST', { timeout: 30_000 });
    await finish.click();
    const done = page.getByText('כל הכבוד!', { exact: true });
    const repeat = page.getByText('התפילה כבר נרשמה היום');
    await expect(done.or(repeat).first()).toBeVisible({ timeout: 15_000 });
    // Окно повтора здесь = расхождение: строка напоминания была, а молитва уже записана.
    await expect(repeat, 'молитва уже записана, но напоминание показывалось').toHaveCount(0);
    expect((await post).status()).toBe(201);

    // 3. «כל הכבוד!» «סיימת את תפילת <молитва> בהצלחה» → «חזרה למסך ראשי» → /home.
    await expect(done).toBeVisible();
    await expect(page.getByText(`סיימת את תפילת ${prayer} בהצלחה`)).toBeVisible();
    await page.getByRole('button', { name: 'חזרה למסך ראשי' }).click();
    await expect(page).toHaveURL(/\/home$/);

    // 4. Строки молитвы нет, прочие на месте; «תפילות אחרונות» первая — эта молитва.
    const after = await readReminders(page);
    expect(after.map((r) => r.title), `«${prayer}» после записи`).not.toContain(prayer);
    for (const t of others) expect(after.map((r) => r.title), `«${t}» осталась`).toContain(t);
    const recent = await recentFirst(page);
    expect(recent.prayer).toBe(prayer);
    expect(recent.when).toMatch(RECENT_WHEN);

    // 5. Две перезагрузки и новая вкладка — строка не возвращается.
    for (let i = 1; i <= 2; i++) {
      await page.reload();
      const rows = await readReminders(page);
      expect(rows.map((r) => r.title), `reload ${i}`).not.toContain(prayer);
      for (const t of others) expect(rows.map((r) => r.title), `reload ${i}: «${t}»`).toContain(t);
    }
    const tab = await context.newPage();
    try {
      const rows = await homeReminders(tab);
      expect(rows.map((r) => r.title), 'новая вкладка').not.toContain(prayer);
      for (const t of others) expect(rows.map((r) => r.title), `новая вкладка: «${t}»`).toContain(t);
      expect((await recentFirst(tab)).prayer).toBe(prayer);
    } finally {
      await tab.close();
    }
  });
});
